package de.fitnesscoach.domain.plan;

import java.time.Instant;import de.fitnesscoach.data.entity.*;

public final class DefaultPlanAdaptationPolicy implements PlanAdaptationPolicy {
 @Override public PlannedWorkoutEntity adapt(PlannedWorkoutEntity w,DomainEnums.RecoveryRecommendation r,PlannedWorkoutEntity prev,PlannedWorkoutEntity next){PlannedWorkoutEntity x=copy(w);if(r==null||r==DomainEnums.RecoveryRecommendation.UNKNOWN||r==DomainEnums.RecoveryRecommendation.FULL||r==DomainEnums.RecoveryRecommendation.NORMAL)return x;if(r==DomainEnums.RecoveryRecommendation.REST){x.workoutType=DomainEnums.WorkoutType.REST;x.sportType=DomainEnums.SportType.OTHER;x.plannedDurationMinutes=0;x.title="Erholungs-Ruhetag";x.description="Ruhetag aufgrund der aktuellen Erholungsbewertung.";}else if(r==DomainEnums.RecoveryRecommendation.RECOVERY_ONLY){x.workoutType=DomainEnums.WorkoutType.RECOVERY;x.plannedDurationMinutes=Math.min(n(x.plannedDurationMinutes),30);x.title="Regenerationseinheit";x.description="Nur lockere Regeneration; kein Tempo-, Intervall- oder langer Lauf.";}else if(r==DomainEnums.RecoveryRecommendation.REDUCED){if(high(x.workoutType))x.workoutType=DomainEnums.WorkoutType.EASY;x.plannedDurationMinutes=Math.max(15,(int)Math.round(n(x.plannedDurationMinutes)*.7));x.title="Reduziertes Training";x.description="Umfang und Intensität wurden aufgrund der Erholungsbewertung reduziert.";}if(high(x.workoutType)&&((prev!=null&&high(prev.workoutType))||(next!=null&&high(next.workoutType))))x.workoutType=DomainEnums.WorkoutType.EASY;x.status=DomainEnums.WorkoutStatus.ADAPTED;x.version=Math.max(1,w.version+1);x.updatedAt=Instant.now();return x;}
 private int n(Integer v){return v==null?30:v;}private boolean high(DomainEnums.WorkoutType t){return t==DomainEnums.WorkoutType.INTERVAL||t==DomainEnums.WorkoutType.TEMPO||t==DomainEnums.WorkoutType.LONG;}private PlannedWorkoutEntity copy(PlannedWorkoutEntity w){PlannedWorkoutEntity x=new PlannedWorkoutEntity();x.id=w.id;x.planId=w.planId;x.date=w.date;x.sportType=w.sportType;x.workoutType=w.workoutType;x.title=w.title;x.description=w.description;x.plannedDurationMinutes=w.plannedDurationMinutes;x.plannedDistanceKm=w.plannedDistanceKm;x.targetHeartRateMin=w.targetHeartRateMin;x.targetHeartRateMax=w.targetHeartRateMax;x.targetPaceMinSecKm=w.targetPaceMinSecKm;x.targetPaceMaxSecKm=w.targetPaceMaxSecKm;x.status=w.status;x.originalWorkoutId=w.originalWorkoutId;x.version=w.version;x.createdAt=w.createdAt;x.updatedAt=w.updatedAt;return x;}
}
